const fs=require("fs");
const src=fs.readFileSync("modules/common/functions/ShellExec.qml","utf8");
const start=src.indexOf("function execDetachedArgs");
const end=src.indexOf("function openDirectory",start);
if(start<0||end<0) process.exit(90);
const block=src.slice(start,end);
if(!block.includes("const argv = Array.from(args ?? [])")) process.exit(91);
if(!block.includes('argv[index] = String(argv[index] ?? "")')) process.exit(92);
if(!block.includes("argv.length = writeIndex")) process.exit(93);
if(block.includes(".map(arg => String(arg ?? \"\")).filter(")) process.exit(94);

function oldNorm(args,stringFn=String){
  return Array.from(args ?? []).map(arg=>stringFn(arg ?? "")).filter(arg=>arg.length>0);
}
function newNorm(args,stringFn=String){
  const argv=Array.from(args ?? []);
  for(let i=0;i<argv.length;i++) argv[i]=stringFn(argv[i] ?? "");
  let w=0;
  for(let r=0;r<argv.length;r++){
    const normalized=argv[r];
    if(normalized.length>0) argv[w++]=normalized;
  }
  argv.length=w;
  return argv;
}
function same(a,b){
  return JSON.stringify(a)===JSON.stringify(b);
}
const primitives=[
  [],
  [null,undefined,"","a",0,false,true,NaN,Infinity,-0,42n],
  ["a","","b","","c"],
  new Array(4)
];
for(const x of primitives){
  const a=oldNorm(x), b=newNorm(x);
  if(!same(a,b)) process.exit(10);
}

function makeIterable(throwAt=-1){
  const trace=[];
  const values=["a","",0,false,null,"z"];
  const iterable={
    [Symbol.iterator](){
      trace.push("iterator");
      let i=0;
      return {
        next(){
          trace.push("next:"+i);
          if(i>=values.length) return {done:true};
          const idx=i++;
          const value={
            toString(){
              trace.push("toString:"+idx);
              if(idx===throwAt) throw new Error("boom-"+idx);
              return String(values[idx] ?? "");
            }
          };
          return {done:false,value};
        }
      };
    }
  };
  return {iterable,trace};
}
for(let throwAt=-1;throwAt<6;throwAt++){
  const a=makeIterable(throwAt), b=makeIterable(throwAt);
  let ao,bo,ae="",be="";
  try{ao=oldNorm(a.iterable);}catch(e){ae=e.message;}
  try{bo=newNorm(b.iterable);}catch(e){be=e.message;}
  if(!same(ao,bo)||ae!==be||!same(a.trace,b.trace)) process.exit(11);
}

function makeArrayLike(throwAt=-1){
  const trace=[];
  const obj={length:5};
  for(let i=0;i<5;i++){
    Object.defineProperty(obj,i,{
      enumerable:true,
      get(){
        trace.push("get:"+i);
        if(i===throwAt) throw new Error("getboom-"+i);
        return i%2 ? "" : "v"+i;
      }
    });
  }
  return {obj,trace};
}
for(let throwAt=-1;throwAt<5;throwAt++){
  const a=makeArrayLike(throwAt),b=makeArrayLike(throwAt);
  let ao,bo,ae="",be="";
  try{ao=oldNorm(a.obj);}catch(e){ae=e.message;}
  try{bo=newNorm(b.obj);}catch(e){be=e.message;}
  if(!same(ao,bo)||ae!==be||!same(a.trace,b.trace)) process.exit(12);
}

// Stronger phase oracle: a custom String-like function returns objects whose
// length getter is observable. Both algorithms must finish every conversion
// before the first length read.
function makeStringFn(trace){
  return value=>{
    trace.push("string:"+String(value));
    const text=String(value);
    return {
      text,
      get length(){trace.push("length:"+text);return text.length;},
      toJSON(){return text;}
    };
  };
}
for(let c=0;c<10000;c++){
  const source=[String(c),"",c%3?String(c+1):"",null,false];
  const ta=[],tb=[];
  const a=oldNorm(source,makeStringFn(ta));
  const b=newNorm(source,makeStringFn(tb));
  if(!same(a,b)||!same(ta,tb)) process.exit(13);
}
process.exit(0);
